import {CAREERS,ScoreStore,rankScores,cleanName,SCORE_KEY,careerIndex,rocketHeight} from './rally-rules.js?v=3.1.0';
import {formatTime} from './tracks.js';
const $=s=>document.querySelector(s),esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=n=>new Intl.NumberFormat('nb-NO').format(n);
export function insignia(index){const n=CAREERS[index].stars,points='0,-6 1.8,-1.9 6,-1.9 2.8,1 3.8,5.8 0,3.1 -3.8,5.8 -2.8,1 -6,-1.9 -1.8,-1.9';let stars='';for(let i=0;i<n;i++){const cols=Math.min(n,3),row=Math.floor(i/3),count=Math.min(cols,n-row*3),x=32+(i%3-(count-1)/2)*15,y=n>3?23+row*17:31;stars+=`<polygon points="${points}" transform="translate(${x} ${y})"/>`;}
return `<svg class="insignia" viewBox="0 0 64 74" role="img" aria-label="${esc(CAREERS[index].name)} – ${n} stjerner"><path class="badge-field" d="M4 4h56v42L32 69 4 46z"/><path class="badge-edge" d="M9 9h46v34L32 62 9 43z"/>${stars}${index>=3?'<path class="badge-edge" d="M19 52l13 7 13-7"/>':''}${index===5?'<path class="badge-edge" d="M18 14l3-6 5 6 6-7 6 7 5-6 3 6"/>':''}</svg>`;}
const remaining=expires=>{const minutes=Math.max(0,Math.ceil((expires-Date.now())/60000));return minutes>=60?`${Math.floor(minutes/60)} t ${minutes%60} min`:`${minutes} min`;};
export function createLeaderboard({openModal,currentBoard,courseName}){
 const store=new ScoreStore();let driver='',pending=null,timer=0;
 // Retire the previous named 72h board and its indefinitely stored nickname.
 try{localStorage.removeItem('fjordsprint-driver');localStorage.removeItem('fjordsprint-scores-v2');}catch{}
 function rowsHTML(board,limit=10){const rows=rankScores(store.all(),board);return rows.length?rows.slice(0,limit).map((r,i)=>`<tr class="${r.id===pending?.id?'your-score':''}"><td>${i+1}</td><th scope="row">${esc(r.name)}</th><td class="points-cell">${number(r.score)}</td><td>${formatTime(r.timeMs/1000)}</td><td title="${esc(CAREERS[r.rank].name)}">${insignia(r.rank)}<span>${esc(CAREERS[r.rank].name)}</span></td><td>${remaining(r.expiresAt)}</td></tr>`).join(''):'<tr><td colspan="6">Ingen aktive resultater. Fullfør en bane!</td></tr>';}
 function table(board,id,limit=10){return `<div class="table-scroll"><table class="score-table career-table"><caption>${esc(courseName(board.split('-')[0]))} · poengtavle · 48 timer</caption><thead><tr><th>#</th><th>Navn</th><th>Poeng</th><th>Tid</th><th>Karrieresteg</th><th>Igjen</th></tr></thead><tbody id="${id}">${rowsHTML(board,limit)}</tbody></table></div>`;}
 function display(board=currentBoard()){
  clearInterval(timer);const suffix=board.slice(board.indexOf('-'));
  openModal('Poengtavlen · 48 timer',`<p>Beste aktive poengsum per navn. Ved lik poengsum vinner kortest tid. Nye kjøreegenskaper i v3.1 har egne lister; tidligere resultater beholder sitt opprinnelige 48-timersutløp.</p><div class="board-tabs">${['fjord','pass','aurora'].map(id=>`<button class="secondary" data-score-course="${id}" aria-pressed="${board.startsWith(id+'-')}">${esc(courseName(id))}</button>`).join('')}</div><p class="board-note">${board.endsWith('assist')?'Assistert':'Sport'} · ${board.includes('archive')?'Arkivrally':'Tidsløp'} · lokal liste på denne enheten, ikke delt på nett.</p>${table(board,'leaderboard-rows',50)}<p class="board-note">Hvert resultat utløper 48 timer etter målgang. Nye løp forlenger ikke gamle resultater. Utløpte navn fjernes ved neste kontroll mens spillet er åpent, eller når det åpnes igjen. Bruk gjerne kallenavn.</p><p class="board-note">${store.persistent?'Nettleserlagring er aktiv.':'Lagring er blokkert: resultatene finnes bare i denne økten.'}</p><button id="clear-career-scores" class="text-btn">Slett lokale poengresultater</button>`);
  document.querySelectorAll('[data-score-course]').forEach(b=>b.onclick=()=>display(b.dataset.scoreCourse+suffix));let confirmed=false;$('#clear-career-scores').onclick=()=>{if(!confirmed){confirmed=true;$('#clear-career-scores').textContent='Bekreft: slett alle lokale resultater';return;}store.clear();display(board);};
  timer=setInterval(()=>{const el=$('#leaderboard-rows');if(!el||$('#modal-backdrop').classList.contains('hidden'))return clearInterval(timer);el.innerHTML=rowsHTML(board,50);},1000);
 }
 function askDriver(callback){openModal('Hvem sitter bak rattet?',`<p>Navnet følger poengsummen din etter hver bane. Kallenavn er tilstrekkelig.</p><form id="driver-form"><label for="driver-name">Navn eller kallenavn</label><div class="score-input-row"><input id="driver-name" name="driver" autocomplete="nickname" minlength="2" maxlength="20" value="${esc(driver)}" placeholder="Ditt kallenavn" required><button class="primary" type="submit">KLAR TIL START →</button></div><p id="driver-error" role="alert"></p><p class="board-note">Resultater lagres lokalt i 48 timer. Ingen felles nettbasert liste er tilkoblet. Navnet huskes ellers bare mens denne spilløkten er åpen.</p></form>`);$('#driver-name').focus();$('#driver-form').onsubmit=e=>{e.preventDefault();try{driver=cleanName($('#driver-name').value);callback();}catch(error){$('#driver-error').textContent=error.message;}};}
 function ensureDriver(callback){if(driver)return true;askDriver(callback);return false;}
 function begin(board,demo){pending={id:globalThis.crypto?.randomUUID?.()||`rally-${Date.now()}-${Math.random().toString(36).slice(2)}`,board,name:driver,demo};$('#score-entry')?.classList.add('hidden');$('#pilot-name').textContent=demo?'DEMOTUR':driver;}
 function finish(result){const host=$('#score-entry');if(!host)return;if(result.demo){host.innerHTML='<p class="board-note">Demoturer lagrer ikke poeng eller navn.</p>';host.classList.remove('hidden');return;}
  let row,error;try{row=store.add({...result,id:pending.id,name:pending.name});}catch(e){error=e.message;}host.classList.remove('hidden');
  const c=CAREERS[result.rank];host.innerHTML=`<div class="career-result">${insignia(result.rank)}<div><span class="eyebrow">${esc(driver)} · ${result.juice} JUICE</span><h3>${esc(c.name)}</h3><p>${esc(c.motto)}</p></div><div class="score-total"><strong>${number(result.score)}</strong><span>POENG</span></div></div><div class="score-breakdown"><span>Kunnskap <b>${number(result.breakdown.knowledge)}</b></span><span>Troll <b>${number(result.breakdown.trolls)}</b></span><span>Presisjon <b>${result.breakdown.precision}</b></span><span>Fart <b>${result.breakdown.pace}</b></span><span>Kontroll <b>${result.breakdown.control}</b></span></div><p role="status" class="board-note">${error?esc(error):store.persistent?'Automatisk lagret på denne enheten · utløper '+new Date(row.expiresAt).toLocaleString('nb-NO'):'Nettleseren blokkerer lagring. Resultatet finnes bare i denne økten.'}</p>${table(result.board,'result-score-rows')}<button id="result-leaderboard" class="text-btn">Hele poengtavlen →</button><p class="board-note">Spillets karrierestige er humoristisk, ikke en faktisk stillingsstruktur.</p>`;
  $('#result-leaderboard').onclick=()=>display(result.board);
 }
 store.all();setInterval(()=>{store.all();if(pending&&$('#result-score-rows'))$('#result-score-rows').innerHTML=rowsHTML(pending.board);},30000);
 addEventListener('storage',e=>{if(e.key===SCORE_KEY)store.all();});document.addEventListener('visibilitychange',()=>{if(!document.hidden)store.all();});
 return {begin,finish,display,ensureDriver,store,get driver(){return driver;},enabled:false,changeDriver:callback=>askDriver(callback)};
}
export function mountRallyUI(onSkip){
 const hud=document.createElement('section');hud.id='competence-hud';hud.innerHTML='<div class="pilot-line"><span>KOMPETANSEKANONEN</span><b id="pilot-name"></b></div><div class="rally-readouts"><span><b id="juice-value">0</b> JUICE</span><span><b id="troll-value">0</b>/12 TROLL</span></div><div class="water-bar"><i id="water-fill"></i></div><small id="water-label">E / KLIKK / RB · VANN 100 %</small>';$('#hud').append(hud);
 const target=document.createElement('div');target.id='troll-target';target.className='hidden';target.setAttribute('aria-live','polite');$('#hud').append(target);
 const ending=document.createElement('section');ending.id='career-flight';ending.className='hidden';ending.innerHTML=`<div class="rocket-title"><span class="eyebrow">DIREKTORATET FOR VERTIKALE FORFREMMELSER</span><h2>Arkivraketten</h2><p id="rocket-caption">Søknad om oppdrift mottatt.</p></div><div id="career-ladder">${[...CAREERS].map((c,i)=>`<div class="career-rung" data-rank="${i}">${insignia(i)}<div><strong>${esc(c.name)}</strong><small>${c.juice} JUICE</small></div></div>`).reverse().join('')}</div><div class="rocket-altimeter"><strong id="rocket-height">0</strong><span>m over målstreken</span><p id="rocket-juice"></p><button id="skip-rocket" class="secondary">Gå til poengtavlen →</button></div>`;document.body.append(ending);$('#skip-rocket').onclick=onSkip;
}
export function updateRallyUI(game,car,mode,age=0){const flying=mode==='finish'&&!!game;$('#career-flight').classList.toggle('hidden',!flying);document.body.classList.toggle('career-flying',flying);if(!game){$('#troll-target')?.classList.add('hidden');return;}
 $('#juice-value').textContent=game.juice;$('#troll-value').textContent=game.cleared;$('#water-fill').style.width=game.pressure+'%';$('#water-label').textContent=`E / KLIKK / RB · VANN ${Math.floor(game.pressure)} %`;
 const next=game.trolls.find(t=>['entering','active'].includes(t.phase)&&t.s>car.s-3&&t.s-car.s<150);$('#troll-target').classList.toggle('hidden',!next||mode!=='race');if(next&&mode==='race')$('#troll-target').innerHTML=`<span>UNNSKYLDNINGSTROLL · ${Math.max(0,Math.round(next.s-car.s))} m</span><strong>«${esc(next.excuse)}»</strong><small>${next.hp===2?'2 vanntreff':'1 vanntreff til'} · Sikt med bilen. Hold E.</small>`;
 if(flying){const u=Math.max(0,Math.min(1,(age-1.7)/10)),height=rocketHeight(game.juice)*(u*u*(3-2*u));$('#rocket-height').textContent=Math.round(height);$('#rocket-juice').textContent=`${game.juice} JUICE · ${game.correct} RIKTIGE SVAR · ${game.cleared} TROLL`;
 document.querySelectorAll('[data-rank]').forEach(el=>{const rank=Number(el.dataset.rank);el.classList.toggle('reached',height>=CAREERS[rank].height-1);el.classList.toggle('destination',rank===careerIndex(game.juice));});
 $('#rocket-caption').textContent=age<1.7?'Vedlegg 1: en meget stor arkivrakett.':age<4?'Tyngdekraftens innsigelse tas ikke til følge.':age<7?'Møtet flyttes til stratosfæren.':age<10?'Alle stjerner er foreløpig korrekt journalført.':CAREERS[careerIndex(game.juice)].motto;
 }
}
